#include <bits/stdc++.h>
using namespace std;

int main(){
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n; cin>>n;
    vector<int> ksz(n);
    vector<vector<pair<int,int>>> raw(n);
    int totalCells=0;
    for(int i=0;i<n;i++){
        cin>>ksz[i]; raw[i].resize(ksz[i]);
        for(int j=0;j<ksz[i];j++) cin>>raw[i][j].first>>raw[i][j].second;
        totalCells+=ksz[i];
    }

    // Generate all orientations: flip f in {0,1}, rot r in {0,1,2,3}
    // flip: (x,y)->(-x,y), rot CCW: (x,y)->(-y,x)
    auto genOrients=[&](const vector<pair<int,int>>& cells)->vector<tuple<vector<pair<int,int>>,int,int,int,int>>{
        vector<tuple<vector<pair<int,int>>,int,int,int,int>> res;
        set<vector<pair<int,int>>> seen;
        for(int f=0;f<2;f++) for(int r=0;r<4;r++){
            vector<pair<int,int>> t;
            for(auto [x,y]:cells){
                int tx=x,ty=y;
                if(f) tx=-tx;
                for(int rr=0;rr<r;rr++){int nx=-ty,ny=tx;tx=nx;ty=ny;}
                t.push_back({tx,ty});
            }
            int mx=INT_MAX,my=INT_MAX;
            for(auto [x,y]:t){mx=min(mx,x);my=min(my,y);}
            for(auto&[x,y]:t){x-=mx;y-=my;}
            sort(t.begin(),t.end());
            if(seen.insert(t).second){
                int Mx=0,My=0;
                for(auto[x,y]:t){Mx=max(Mx,x);My=max(My,y);}
                res.push_back({t,Mx+1,My+1,r,f});
            }
        }
        return res;
    };

    auto allO=vector<vector<tuple<vector<pair<int,int>>,int,int,int,int>>>(n);
    for(int i=0;i<n;i++) allO[i]=genOrients(raw[i]);

    vector<int> ord(n); iota(ord.begin(),ord.end(),0);
    sort(ord.begin(),ord.end(),[&](int a,int b){return ksz[a]>ksz[b];});

    int sq=(int)ceil(sqrt((double)totalCells));
    long long bestArea=LLONG_MAX;
    int bestW=0,bestH=0;
    vector<int> bx(n),by(n),br(n),bf(n);
    auto ST=chrono::steady_clock::now();
    auto ms=[&](){return chrono::duration_cast<chrono::milliseconds>(chrono::steady_clock::now()-ST).count();};

    for(int W=max(1,sq-10);W<=totalCells&&ms()<9000;W++){
        vector<int> ch(W,0);
        set<long long> occ;
        auto K=[](int x,int y)->long long{return(long long)x*100000+y;};
        vector<int> px(n),py(n),pr(n),pf(n);
        bool ok=true; int mxH=0;
        for(int idx=0;idx<n;idx++){
            int i=ord[idx]; int bs=INT_MAX,bxx=-1,byy=-1,boi=-1;
            for(int oi=0;oi<(int)allO[i].size();oi++){
                auto&[cells,w,h,r,fl]=allO[i][oi];
                if(w>W) continue;
                for(int x=0;x<=W-w;x++){
                    int my=0;
                    for(auto[cx,cy]:cells) my=max(my,ch[x+cx]-cy);
                    if(my<0)my=0;
                    for(int y=my;y<=my+30;y++){
                        int nh=max(mxH,y+h);
                        int sc=nh*100000+y*1000+x;
                        if(sc>=bs) break;
                        bool good=true;
                        for(auto[cx,cy]:cells) if(occ.count(K(x+cx,y+cy))){good=false;break;}
                        if(good){bs=sc;bxx=x;byy=y;boi=oi;break;}
                    }
                }
            }
            if(bxx<0){ok=false;break;}
            auto&[cells,w,h,r,fl]=allO[i][boi];
            px[i]=bxx;py[i]=byy;pr[i]=r;pf[i]=fl;
            for(auto[cx,cy]:cells){occ.insert(K(bxx+cx,byy+cy));ch[bxx+cx]=max(ch[bxx+cx],byy+cy+1);mxH=max(mxH,byy+cy+1);}
        }
        if(!ok) continue;
        long long a=(long long)W*mxH;
        if(a<bestArea){bestArea=a;bestW=W;bestH=mxH;bx=px;by=py;br=pr;bf=pf;}
    }

    cout<<bestW<<" "<<bestH<<"\n";
    for(int i=0;i<n;i++) cout<<bx[i]<<" "<<by[i]<<" "<<br[i]<<" "<<bf[i]<<"\n";
}
